package android.app;
public class NotificationManager { public static final int IMPORTANCE_NONE=0,IMPORTANCE_MIN=1,IMPORTANCE_LOW=2,IMPORTANCE_DEFAULT=3,IMPORTANCE_HIGH=4,IMPORTANCE_MAX=5; private final java.util.HashMap<String,NotificationChannel> channels=new java.util.HashMap<String,NotificationChannel>(); public void notify(int id,Notification n) {} public void notify(String tag,int id,Notification n) {} public void cancel(int id) {} public void cancel(String tag,int id) {} public void cancelAll() {} public void createNotificationChannel(NotificationChannel c) { channels.put(c.getId(),c); } public NotificationChannel getNotificationChannel(String id) { return channels.get(id); } public void deleteNotificationChannel(String id) { channels.remove(id); } public boolean areNotificationsEnabled() { return true; } }
